    """Tile 8-cells with 2x2 squares and three-cell L pieces.

    2x2 square -> 1; L missing top-left -> 2, missing bottom-left -> 3,
    missing top-right -> 4.
    """
    h, w = len(grid), len(grid[0])
    remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    output = [[0 for _ in range(w)] for _ in range(h)]
    pieces = [
        (1, ((0, 0), (0, 1), (1, 0), (1, 1))),
        (2, ((0, 1), (1, 0), (1, 1))),
        (3, ((0, 0), (0, 1), (1, 1))),
        (4, ((0, 0), (1, 0), (1, 1))),
    ]

    def place(cells):
        if not cells:
            return True
        r, c = min(cells)
        for color, shape in pieces:
            for dr, dc in shape:
                top, left = r - dr, c - dc
                covered = {(top + sr, left + sc) for sr, sc in shape}
                if covered <= cells:
                    for rr, cc in covered:
                        output[rr][cc] = color
                    if place(cells - covered):
                        return True
                    for rr, cc in covered:
                        output[rr][cc] = 0
        return False

    if not place(remaining):
        raise ValueError("Grid cannot be tiled by the demonstrated pieces")
    return output


if __name__ == "__main__":
